12	/**
13	 * Normalize a Date that may have been constructed from a bare YYYY-MM-DD UTC string
14	 * (midnight UTC) into local calendar date so formatting/addition never shifts by timezone.
15	 */
16	function normalizeCalendarDate(date: Date): Date {
17	  if (!isValid(date)) return date;
18	  if (
19	    date.getUTCHours() === 0 &&
20	    date.getUTCMinutes() === 0 &&
21	    date.getUTCSeconds() === 0 &&
22	    date.getUTCMilliseconds() === 0 &&
23	    (date.getHours() !== 0 || date.getDate() !== date.getUTCDate())
24	  ) {
25	    return new Date(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate());
26	  }
27	  return date;
28	}
