30	/**
31	 * Format a date for display in Spanish locale
32	 */
33	export function formatDate(date: Date, formatStr: string = "d 'de' MMMM, yyyy"): string {
34	  if (!isValid(date)) return "Fecha inválida";
35	  return format(normalizeCalendarDate(date), formatStr, { locale: es });
